function tarpRain(posts: number[]): number {
  let i = 0, j = posts.length - 1, best = 0;
  while (i < j) {
    best = Math.max(best, Math.min(posts[i], posts[j]) * (j - i));
    if (posts[i] < posts[j]) i++; else j--;
  }
  return best;
}
